/**
 * Twins of the three ranked feed reads (plan 10.11 section 4, ZP-GROUPB-READS-2): public.entities_ranked_for_feed,
 * entities_ranked_for_feed_by_type and entities_ranked_for_topics. Pure functions over in-memory row sets that return what the SQL
 * returns, held to golden output from a scratch Postgres (`__tests__/feeds.golden.test.ts`, generated by
 * `api/scripts/groupb/gen_golden_feeds.py`). SQL stays the source of truth; nothing here serves a request, and the flag-off shadow
 * (`../rankedReadsShadow.ts`) compares a twin against the Postgres read.
 *
 * Fidelity notes (each is a place the SQL is subtle, and each is in the golden grid):
 *  - `trim(text)` removes spaces only, so a name of tabs or newlines is a usable name. JS `trim()` would not agree.
 *  - `created_after`/`created_before` are TEXT compares on `created_at`, code-unit order (digits), as in a C-collation database.
 *  - the name filter needs a non-blank name IN one of `space_ids` when given, not merely a name somewhere; an empty array matches
 *    no entity, NULL means any space.
 *  - the by-type and by-topic reads score from the derived `entity_type_ranking` / `entity_topic_ranking` rows, not from
 *    `entity_ranking_scores`, and apply `max_per_*` per walk BEFORE collapsing an entity that several walks return.
 *  - an entity absent from `entities` is dropped at the final join, whatever the derived rows say.
 *  - entities_ranked_for_topics: a Debate-typed walk with `space_ids` also needs the debate tag relation in one of those spaces;
 *    `debate_tagged_claims` swaps Claim for Debate in `type_ids`; with `match_all` and more than one topic only the rarest topic
 *    (fewest rows, then lowest id) is walked and the others are required; the two argument errors carry SQLSTATE 22023.
 */

import type {EntityRow, RelationRow} from "./trending"
import {TYPES} from "./trending"

export const SYSTEM_TYPE = "88b3d6ad-288c-529c-a212-0e1c24819185"
export const CLAIM_TYPE = "96f859ef-a1ca-4b22-9372-c86ad58b694b"
/** The Debate type the debate-tagged-claims feed walks, and the target of the debate tag relation. */
export const DEBATE_WALK_TYPE = "55c95b26-26f8-482c-b973-9ea99dfde438"
export const DEBATE_TAG = "25709034-1ba5-406f-94e4-d4af90042fba"

export type FeedRelation = Pick<RelationRow, "type_id" | "from_entity_id" | "to_entity_id" | "space_id">
export interface NameRow {
	entity_id: string
	space_id: string
	text: string | null
}
export interface ScoreRow {
	entity_id: string
	ranking_score: number
}
export interface TypeRankingRow {
	type_id: string
	entity_id: string
	ranking_score: number
}
export interface TopicRankingRow {
	topic_id: string
	type_id: string
	entity_id: string
	ranking_score: number
	created_epoch: number | null
}
export interface FeedData {
	entities: EntityRow[]
	relations: FeedRelation[]
	/** Name-property values (property_id = Name); the property filter is the loader's. */
	names: NameRow[]
	scores: ScoreRow[]
	blocklist: {entity_id: string}[]
	exclusions: {type_id: string}[]
	typeRanking: TypeRankingRow[]
	topicRanking: TopicRankingRow[]
}

export class FeedArgumentError extends Error {
	readonly code = "22023"
}

const trimSpaces = (s: string) => s.replace(/^ +| +$/g, "")
const byDesc =
	<T>(score: (r: T) => number, id: (r: T) => string) =>
	(a: T, b: T) =>
		score(b) - score(a) || (id(a) < id(b) ? 1 : id(a) > id(b) ? -1 : 0)

export class Feeds {
	private readonly created = new Map<string, string>()
	private readonly entityRows = new Map<string, EntityRow>()
	private readonly namesBy = new Map<string, NameRow[]>()
	private readonly blocked = new Set<string>()
	private readonly system = new Set<string>()
	private readonly excludedTypeEntity = new Set<string>()
	private readonly typesOf = new Map<string, Set<string>>()
	private readonly tags: FeedRelation[] = []

	constructor(private readonly d: FeedData) {
		for (const e of d.entities) {
			this.created.set(e.id, e.created_at)
			this.entityRows.set(e.id, e)
		}
		for (const n of d.names) {
			const a = this.namesBy.get(n.entity_id) ?? []
			a.push(n)
			this.namesBy.set(n.entity_id, a)
		}
		for (const b of d.blocklist) this.blocked.add(b.entity_id)
		const excluded = new Set(d.exclusions.map((x) => x.type_id))
		for (const r of d.relations) {
			if (r.type_id === SYSTEM_TYPE) this.system.add(r.from_entity_id)
			if (r.type_id === TYPES) {
				if (excluded.has(r.to_entity_id)) this.excludedTypeEntity.add(r.from_entity_id)
				const s = this.typesOf.get(r.from_entity_id) ?? new Set<string>()
				s.add(r.to_entity_id)
				this.typesOf.set(r.from_entity_id, s)
			}
			if (r.type_id === DEBATE_TAG && r.to_entity_id === DEBATE_WALK_TYPE) this.tags.push(r)
		}
	}

	private named(id: string, spaces: string[] | null): boolean {
		return (this.namesBy.get(id) ?? []).some(
			(v) => v.text !== null && trimSpaces(v.text).length > 0 && (spaces === null || spaces.includes(v.space_id)),
		)
	}

	private inWindow(id: string, after: string | null, before: string | null): boolean {
		const c = this.created.get(id)
		return c !== undefined && (after === null || c > after) && (before === null || c <= before)
	}

	private tagged(id: string, spaces: string[] | null): boolean {
		return this.tags.some((t) => t.from_entity_id === id && (spaces === null || spaces.includes(t.space_id)))
	}

	/** public.entities_ranked_for_feed */
	entitiesRankedForFeed(
		min: number | null,
		after: string | null,
		before: string | null,
		spaces: string[] | null,
		types: string[] | null,
	): EntityRow[] {
		const out: {e: EntityRow; score: number}[] = []
		for (const rs of this.d.scores) {
			const e = this.entityRows.get(rs.entity_id)
			if (!e) continue
			if (min !== null && !(rs.ranking_score >= min)) continue
			if (after !== null && !(e.created_at > after)) continue
			if (before !== null && !(e.created_at <= before)) continue
			if (!this.named(e.id, spaces)) continue
			if (types !== null && !types.some((t) => this.typesOf.get(e.id)?.has(t))) continue
			if (this.blocked.has(e.id) || this.system.has(e.id) || this.excludedTypeEntity.has(e.id)) continue
			out.push({e, score: rs.ranking_score})
		}
		return out
			.sort(
				byDesc(
					(r) => r.score,
					(r) => r.e.id,
				),
			)
			.map((r) => r.e)
	}

	/** public.entities_ranked_for_feed_by_type */
	entitiesRankedForFeedByType(
		types: string[] | null,
		min: number | null,
		after: string | null,
		before: string | null,
		spaces: string[] | null,
		maxPerType: number | null,
	): EntityRow[] {
		const best = new Map<string, number>()
		for (const tid of types ?? []) {
			let rows = this.d.typeRanking.filter(
				(r) =>
					r.type_id === tid &&
					(min === null || r.ranking_score >= min) &&
					this.inWindow(r.entity_id, after, before) &&
					this.named(r.entity_id, spaces) &&
					!this.blocked.has(r.entity_id) &&
					!this.system.has(r.entity_id) &&
					!this.excludedTypeEntity.has(r.entity_id),
			)
			rows = rows.sort(
				byDesc(
					(r) => r.ranking_score,
					(r) => r.entity_id,
				),
			)
			if (maxPerType !== null) rows = rows.slice(0, Math.max(0, maxPerType))
			for (const r of rows)
				best.set(r.entity_id, Math.max(best.get(r.entity_id) ?? Number.NEGATIVE_INFINITY, r.ranking_score))
		}
		return [...best]
			.filter(([id]) => this.entityRows.has(id))
			.sort(
				byDesc(
					([, s]) => s,
					([id]) => id,
				),
			)
			.map(([id]) => this.entityRows.get(id)!)
	}

	/** public.entities_ranked_for_topics. Throws FeedArgumentError where the SQL raises 22023. */
	entitiesRankedForTopics(p: {
		topics: string[] | null
		weights: number[] | null
		types: string[] | null
		min: number | null
		after: string | null
		before: string | null
		spaces: string[] | null
		maxPerTopic: number | null
		debateTaggedClaims: boolean
		sortBy: string | null
		matchAll: boolean
	}): EntityRow[] {
		const topicIds = p.topics ?? []
		if (p.weights !== null && p.weights.length !== topicIds.length)
			throw new FeedArgumentError(
				`topicWeights must have one weight per topic (got ${p.weights.length} for ${topicIds.length} topics)`,
			)
		if (p.sortBy !== "best" && p.sortBy !== "new")
			throw new FeedArgumentError(`sortBy must be best or new (got ${p.sortBy ?? "<NULL>"})`)
		const isNew = p.sortBy === "new"

		const walkTypes =
			p.debateTaggedClaims && p.types !== null
				? p.types.map((t) => (t === CLAIM_TYPE ? DEBATE_WALK_TYPE : t))
				: p.types
		let walkTopics: string[]
		let weights: number[]
		let others: string[] = []
		if (p.matchAll && topicIds.length > 1) {
			const count = (t: string) => this.d.topicRanking.filter((x) => x.topic_id === t).length
			const rarest = [...topicIds].sort((a, b) => count(a) - count(b) || (a < b ? -1 : a > b ? 1 : 0))[0]!
			walkTopics = [rarest]
			others = topicIds.filter((t) => t !== rarest)
			weights = [0]
		} else {
			walkTopics = topicIds
			weights = p.weights ?? topicIds.map(() => 0)
		}
		const inOthers = (id: string) =>
			others.every((o) => this.d.topicRanking.some((x) => x.entity_id === id && x.topic_id === o))
		const weighted = (r: TopicRankingRow, w: number): number | null =>
			isNew ? r.created_epoch : r.ranking_score + w

		const stage: {entity_id: string; weighted: number | null}[] = []
		walkTopics.forEach((tid, i) => {
			const w = weights[i] ?? 0
			let rows: {entity_id: string; weighted: number | null}[]
			const base = (r: TopicRankingRow) =>
				(p.min === null || r.ranking_score >= p.min) &&
				(p.after === null && p.before === null ? true : this.inWindow(r.entity_id, p.after, p.before)) &&
				(p.spaces === null || this.named(r.entity_id, p.spaces)) &&
				!this.blocked.has(r.entity_id) &&
				inOthers(r.entity_id)
			if (walkTypes !== null) {
				rows = []
				for (const yid of walkTypes) {
					let part = this.d.topicRanking.filter(
						(r) =>
							r.topic_id === tid &&
							r.type_id === yid &&
							base(r) &&
							(yid !== DEBATE_WALK_TYPE || p.spaces === null || this.tagged(r.entity_id, p.spaces)),
					)
					part = this.limitOrdered(part, isNew, p.maxPerTopic)
					for (const r of part) rows.push({entity_id: r.entity_id, weighted: weighted(r, w)})
				}
			} else {
				let part = this.d.topicRanking.filter(
					(r) =>
						r.topic_id === tid &&
						base(r) &&
						(!p.debateTaggedClaims ||
							!this.d.topicRanking.some(
								(c) =>
									c.topic_id === r.topic_id &&
									c.entity_id === r.entity_id &&
									c.type_id === CLAIM_TYPE,
							) ||
							this.tagged(r.entity_id, p.spaces)),
				)
				// SELECT DISTINCT (order key, entity, weighted): the same entity under several types counts once toward the limit.
				const seen = new Set<string>()
				part = part.filter((r) => {
					const k = `${isNew ? r.created_epoch : r.ranking_score}|${r.entity_id}|${weighted(r, w)}`
					if (seen.has(k)) return false
					seen.add(k)
					return true
				})
				part = this.limitOrdered(part, isNew, p.maxPerTopic)
				rows = part.map((r) => ({entity_id: r.entity_id, weighted: weighted(r, w)}))
			}
			stage.push(...rows)
		})

		// DISTINCT ON (entity) keeping the best weighted (NULLS LAST), then weighted DESC NULLS LAST, entity DESC, LIMIT.
		const pick = new Map<string, number | null>()
		for (const r of stage) {
			const cur = pick.get(r.entity_id)
			if (
				cur === undefined ||
				(cur === null && r.weighted !== null) ||
				(r.weighted !== null && cur !== null && r.weighted > cur)
			)
				pick.set(r.entity_id, r.weighted)
		}
		let merged = [...pick].map(([entity_id, w]) => ({entity_id, weighted: w}))
		merged.sort(byNullsLast)
		if (p.maxPerTopic !== null) merged = merged.slice(0, Math.max(0, p.maxPerTopic))
		return merged.filter((r) => this.entityRows.has(r.entity_id)).map((r) => this.entityRows.get(r.entity_id)!)
	}

	private limitOrdered(rows: TopicRankingRow[], isNew: boolean, cap: number | null): TopicRankingRow[] {
		const key = (r: TopicRankingRow) => (isNew ? r.created_epoch : r.ranking_score)
		const sorted = [...rows].sort((a, b) => {
			const ka = key(a)
			const kb = key(b)
			if (ka !== kb) {
				if (ka === null) return 1
				if (kb === null) return -1
				return kb - ka
			}
			return a.entity_id < b.entity_id ? 1 : a.entity_id > b.entity_id ? -1 : 0
		})
		return cap === null ? sorted : sorted.slice(0, Math.max(0, cap))
	}
}

const byNullsLast = (
	a: {entity_id: string; weighted: number | null},
	b: {entity_id: string; weighted: number | null},
) => {
	if (a.weighted !== b.weighted) {
		if (a.weighted === null) return 1
		if (b.weighted === null) return -1
		return b.weighted - a.weighted
	}
	return a.entity_id < b.entity_id ? 1 : a.entity_id > b.entity_id ? -1 : 0
}
